record.field:
if not env.user.has_group('base.group_system'):
    raise Warning('Only system administrators can run RFB sequence alignment.')
rows = records._adjust_rfb_sequences(dry_run=True)
changed = sum(1 for row in rows if row['changed'])
log('RFB sequence dry run: %s sequence(s) would change.' % changed, level='info')
action = {
    'type': 'ir.actions.client',
    'tag': 'display_notification',
    'params': {
        'title': 'RFB Sequence Dry Run',
        'message': '%s sequence(s) would change. See the server log for details.' % changed,
        'type': 'info',
        'sticky': False,
    },
}

if not env.user.has_group('base.group_system'):
    raise Warning('Only system administrators can run RFB sequence alignment.')
rows = records._adjust_rfb_sequences(dry_run=False)
changed = sum(1 for row in rows if row['changed'])
log('RFB sequence alignment applied: %s sequence(s) changed.' % changed, level='info')
action = {
    'type': 'ir.actions.client',
    'tag': 'display_notification',
    'params': {
        'title': 'RFB Sequences Aligned',
        'message': '%s sequence(s) changed.' % changed,
        'type': 'success',
        'sticky': False,
    },
}
